import { Command } from '@commander-js/extra-typings';
import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import { asPosix } from '../../base/path_utils';
import { parseStudyFile } from '../utils/study_json_utils';

const REPO_BLOB_BASE = 'https://github.com/brave/brave-variations/blob/main/';

export default function createCommand() {
  return new Command('find_outdated_studies')
    .description(
      'Find outdated studies: no max_version set and last modified N+ months ago. ' +
        '// !Expiry Date: <ISO-8601> overrides the last-modified cutoff.',
    )
    .argument(
      '[studies_dir]',
      'path to the directory containing study files',
      'studies',
    )
    .option(
      '-m, --months <months>',
      'minimum months since last modification',
      (value) => {
        const months = Number.parseInt(value, 10);
        if (!Number.isFinite(months) || months < 0) {
          throw new Error(`Invalid --months value: ${value}`);
        }
        return months;
      },
      3,
    )
    .option(
      '-o, --output <file>',
      'write Slack mrkdwn JSON payload to the given file',
    )
    .action(main);
}

interface Options {
  months: number;
  output?: string;
}

interface OutdatedStudy {
  name: string;
  filePath: string;
  date: Date;
  author: string;
}

async function main(studiesDir: string, options: Options) {
  const outdated = await findOutdatedStudies(studiesDir, options.months);
  outdated.sort(
    (a, b) =>
      a.date.getTime() - b.date.getTime() || a.name.localeCompare(b.name),
  );

  if (options.output !== undefined) {
    if (outdated.length > 0) {
      fs.writeFileSync(options.output, toSlackPayload(outdated));
    }
    return;
  }

  for (const study of outdated) {
    console.log(`${study.name}\t${formatDate(study.date)}\t${study.author}`);
  }
}

async function findOutdatedStudies(
  studiesDir: string,
  months: number,
): Promise<OutdatedStudy[]> {
  const files = (await fs.promises.readdir(studiesDir))
    .filter((file) => file.endsWith('.json5'))
    .sort();
  const cutoff = new Date();
  cutoff.setMonth(cutoff.getMonth() - months);

  const outdated: OutdatedStudy[] = [];

  for (const file of files) {
    const filePath = path.join(studiesDir, file);
    const content = await fs.promises.readFile(filePath, 'utf8');
    const { studies, errors, expiryDate } = parseStudyFile(filePath, content);
    if (errors.length > 0) {
      console.error(`Error parsing ${filePath}:\n${errors.join('\n')}`);
      process.exit(1);
    }

    if (studies.every((study) => study.filter?.max_version)) {
      continue;
    }

    const { commit, date } = getLastCommit(filePath);
    if (isWithinReviewWindow(date, cutoff, expiryDate)) {
      continue;
    }

    outdated.push({
      name: file.replace(/\.json5$/, ''),
      filePath,
      date,
      author: findPrAuthor(commit),
    });
  }

  return outdated;
}

// Last-modified on/after cutoff means the study is still in the review window.
// `expiryDate` overrides that: the study stays in the window until that
// timestamp, then is reported regardless of last-modified.
export function isWithinReviewWindow(
  lastModified: Date,
  cutoff: Date,
  expiryDate: Date | undefined,
  now = new Date(),
): boolean {
  if (expiryDate !== undefined) {
    return expiryDate >= now;
  }
  return lastModified >= cutoff;
}

function getLastCommit(filePath: string): {
  commit: string;
  date: Date;
} {
  const output = execFileSync(
    'git',
    ['log', '-1', '--format=%H%n%cI', '--', filePath],
    { encoding: 'utf8' },
  ).trim();
  if (!output) {
    console.error(`Failed to get last commit for ${filePath}`);
    process.exit(1);
  }
  const [commit, date] = output.split('\n');
  return { commit, date: new Date(date) };
}

function findPrAuthor(commit: string): string {
  if (!commit) {
    return 'unknown';
  }
  try {
    const output = execFileSync(
      'gh',
      [
        'pr',
        'list',
        '--search',
        commit,
        '--state',
        'all',
        '--json',
        'author',
        '--limit',
        '1',
      ],
      { encoding: 'utf8' },
    ).trim();
    const prs = JSON.parse(output) as {
      author?: { login?: string; name?: string };
    }[];
    const login = prs[0]?.author?.login ?? '';
    const name = prs[0]?.author?.name ?? '';
    if (login && name) {
      return `${login} (${name})`;
    }
    return login || name || 'unknown';
  } catch (e) {
    const message = e instanceof Error ? e.message : String(e);
    console.error(`Failed to look up PR for ${commit}: ${message}`);
    process.exit(1);
  }
}

function formatDate(date: Date): string {
  return date.toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

function toSlackPayload(studies: OutdatedStudy[]): string {
  const blocks = [
    {
      type: 'header',
      text: { type: 'plain_text', text: 'Outdated studies' },
    },
    ...studies.map((study) => {
      const fileUrl = REPO_BLOB_BASE + asPosix(study.filePath);
      const name = `<${fileUrl}|${study.name}>`;
      const date = formatDate(study.date);
      return {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${name}, ${date}, ${study.author}`,
        },
      };
    }),
  ];

  return (
    JSON.stringify({ text: 'Outdated studies detected', blocks }, null, 2) +
    '\n'
  );
}


